<?php require __DIR__.'/config/database.php';
$packages=$conn->query('SELECT id,name,destination,duration,price FROM packages WHERE is_active=1 ORDER BY name')->fetch_all(MYSQLI_ASSOC);$selected=filter_input(INPUT_GET,'package',FILTER_VALIDATE_INT)?:0;$error='';$success='';$code='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 $token=$_POST['csrf']??'';if(!hash_equals($_SESSION['csrf']??'', $token)){$error='Sesi formulir kedaluwarsa. Muat ulang halaman dan coba lagi.';}else{
  $pid=(int)($_POST['package_id']??0);$name=trim($_POST['customer_name']??'');$email=trim($_POST['email']??'');$phone=trim($_POST['phone']??'');$date=$_POST['departure_date']??'';$people=(int)($_POST['participants']??0);$notes=trim($_POST['notes']??'');
  $st=$conn->prepare('SELECT id,name,price FROM packages WHERE id=? AND is_active=1');$st->bind_param('i',$pid);$st->execute();$pkg=$st->get_result()->fetch_assoc();
  if(!$pkg||$name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||!preg_match('/^[0-9+() .-]{8,30}$/',$phone)||$people<1||$people>100||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date)||$date<date('Y-m-d')){$error='Periksa kembali data. Tanggal harus hari ini atau setelahnya, email/nomor telepon valid, dan peserta 1–100 orang.';}else{
   $code='NW'.date('ymd').strtoupper(bin2hex(random_bytes(3)));$total=(float)$pkg['price']*$people;$ins=$conn->prepare("INSERT INTO bookings (booking_code,package_id,customer_name,email,phone,departure_date,participants,total_price,notes) VALUES (?,?,?,?,?,?,?,?,?)");$ins->bind_param('sissssids',$code,$pid,$name,$email,$phone,$date,$people,$total,$notes);$ins->execute();$success='Booking berhasil dicatat. Simpan kode booking Anda untuk konfirmasi dengan admin.';
   $_SESSION['booking_result']=['code'=>$code,'name'=>$name,'package'=>$pkg['name'],'date'=>$date,'people'=>$people,'total'=>$total];
  }
 }
}
if(!isset($_SESSION['csrf']))$_SESSION['csrf']=bin2hex(random_bytes(32));$result=$_SESSION['booking_result']??null;unset($_SESSION['booking_result']);
?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Booking Paket — Nusindo Wisata</title><link rel="stylesheet" href="assets/css/style.css"></head><body><header class="container"><nav class="nav"><a class="brand" href="index.php"><img class="brand-logo" src="gambar/logofix.svg" alt="Logo Nusindo Wisata" onerror="this.hidden=true;this.nextElementSibling.hidden=false"><span class="brand-mark" hidden>N</span><span>Nusindo Wisata.</span></a><div class="navlinks"><a href="index.php#paket">Paket Wisata</a><a href="index.php#kontak">Kontak</a></div></nav></header><main class="container"><div class="booking-back"><a class="btn btn-outline" href="index.php#paket">← Kembali ke Paket</a></div><section class="form-shell"><div class="kicker">Pemesanan perjalanan</div><h1>Yuk, rencanakan liburanmu.</h1><p class="muted">Isi detail di bawah. Pesanan akan masuk ke dashboard admin untuk ditinjau dan dikonfirmasi.</p>
<?php if($error):?><div class="notice error"><?=e($error)?></div><?php endif;?><?php if($success&&$result):?><div class="notice"><strong>✓ <?=e($success)?></strong><div style="font-size:1.2rem;margin-top:8px">Kode booking: <strong><?=e($result['code'])?></strong></div><p style="margin-bottom:0">Paket: <?=e($result['package'])?> · <?=e($result['people'])?> peserta · <?=e($result['date'])?><br>Estimasi total: <strong><?=rupiah($result['total'])?></strong></p></div><?php endif;?>
<form method="post" id="bookingForm"><input type="hidden" name="csrf" value="<?=e($_SESSION['csrf'])?>"><div class="form-grid"><div class="field full"><label for="package_id">Pilih paket wisata *</label><select id="package_id" name="package_id" required><option value="">Pilih paket</option><?php foreach($packages as $p):?><option value="<?=$p['id']?>" data-price="<?=$p['price']?>" <?=($selected===$p['id']||(isset($_POST['package_id'])&&(int)$_POST['package_id']===$p['id']))?'selected':''?>><?=e($p['name'])?> — <?=rupiah($p['price'])?>/orang</option><?php endforeach;?></select></div><div class="field"><label for="customer_name">Nama lengkap *</label><input id="customer_name" name="customer_name" required maxlength="120" autocomplete="name" value="<?=e($_POST['customer_name']??'')?>" placeholder="Nama sesuai identitas"></div><div class="field"><label for="email">Email *</label><input id="email" name="email" type="email" required maxlength="150" autocomplete="email" value="<?=e($_POST['email']??'')?>" placeholder="nama@email.com"></div><div class="field"><label for="phone">Nomor WhatsApp *</label><input id="phone" name="phone" type="tel" required maxlength="30" value="<?=e($_POST['phone']??'')?>" placeholder="08xxxxxxxxxx"></div><div class="field"><label for="departure_date">Tanggal keberangkatan *</label><input id="departure_date" name="departure_date" type="date" min="<?=date('Y-m-d')?>" required value="<?=e($_POST['departure_date']??'')?>"></div><div class="field"><label for="participants">Jumlah peserta *</label><input id="participants" name="participants" type="number" min="1" max="100" value="<?=e($_POST['participants']??'1')?>" required></div><div class="field full"><label for="notes">Catatan tambahan (opsional)</label><textarea id="notes" name="notes" rows="3" maxlength="1500" placeholder="Permintaan khusus, titik penjemputan, dll."><?=e($_POST['notes']??'')?></textarea></div></div><div class="summary"><div class="summary-line"><span>Harga per orang</span><strong id="unitPrice">—</strong></div><div class="summary-line"><span>Jumlah peserta</span><strong id="peopleCount">1 orang</strong></div><div class="summary-line summary-total"><span>Estimasi total</span><strong id="totalPrice">—</strong></div><small class="muted">Harga akhir dan ketersediaan akan dikonfirmasi oleh admin.</small></div><button class="btn btn-primary" style="width:100%" type="submit">Kirim Permintaan Booking →</button><p class="muted" style="font-size:.82rem;text-align:center">Pengiriman formulir belum merupakan konfirmasi atau pembayaran.</p></form></section></main><footer class="footer"><div class="container footer-inner"><a class="brand" href="index.php" style="color:white"><img class="brand-logo" src="gambar/logofix.svg" alt="Logo Nusindo Wisata" onerror="this.hidden=true;this.nextElementSibling.hidden=false"><span class="brand-mark" hidden>N</span><span>Nusindo Wisata.</span></a><span>© <?=date('Y')?> Nusindo Wisata</span></div></footer><script>
const pkg=document.getElementById('package_id'), people=document.getElementById('participants'), unit=document.getElementById('unitPrice'), count=document.getElementById('peopleCount'), total=document.getElementById('totalPrice');function fmt(n){return new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(n)}function calc(){const opt=pkg.options[pkg.selectedIndex],price=Number(opt?.dataset.price||0),qty=Math.max(1,Math.min(100,Number(people.value||1)));unit.textContent=price?fmt(price):'—';count.textContent=qty+' orang';total.textContent=price?fmt(price*qty):'—'}pkg.addEventListener('change',calc);people.addEventListener('input',calc);calc();</script></body></html>
